import{_ as t,a0 as p,w as d,s as o,ao as h,I as l,x as a,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何统计 Linux 中文件和文件夹/目录的数量 | LCTT x X-CMD","titleTemplate":false,"description":"如何统计 Linux 中文件和文件夹/目录的数量 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何统计 Linux 中文件和文件夹/目录的数量 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何统计 Linux 中文件和文件夹/目录的数量 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20171212 How To Count The Number Of Files And Folders-Directories In Linux","title":"如何统计 Linux 中文件和文件夹/目录的数量","tag":"201802","desc":""},"relativePath":"201802/20171212 How To Count The Number Of Files And Folders-Directories In Linux.md","filePath":"[post].md"}'),c={name:"201802/20171212 How To Count The Number Of Files And Folders-Directories In Linux.md"};function r(g,s,k,b,u,f){const e=p("Link");return d(),o("div",null,[s[13]||(s[13]=h(`<h1 id="如何统计-linux-中文件和文件夹-目录的数量" tabindex="-1">如何统计 Linux 中文件和文件夹/目录的数量 <a class="header-anchor" href="#如何统计-linux-中文件和文件夹-目录的数量" aria-label="Permalink to “如何统计 Linux 中文件和文件夹/目录的数量”">​</a></h1><p>嗨，伙计们，今天我们再次带来一系列可以多方面帮助到你的复杂的命令。 通过操作命令，可以帮助您计数当前目录中的文件和目录、递归计数，统计特定用户创建的文件列表等。</p><p>在本教程中，我们将向您展示如何使用多个命令，并使用 <code>ls</code>、<code>egrep</code>、<code>wc</code> 和 <code>find</code> 命令执行一些高级操作。 下面的命令将可用在多个方面。</p><p>为了实验，我打算总共创建 7 个文件和 2 个文件夹（5 个常规文件和 2 个隐藏文件）。 下面的 <code>tree</code> 命令的输出清楚的展示了文件和文件夹列表。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tree -a /opt</span></span>
<span class="line"><span>/opt</span></span>
<span class="line"><span>├── magi</span></span>
<span class="line"><span>│   └── 2g</span></span>
<span class="line"><span>│   ├── test5.txt</span></span>
<span class="line"><span>│   └── .test6.txt</span></span>
<span class="line"><span>├── test1.txt</span></span>
<span class="line"><span>├── test2.txt</span></span>
<span class="line"><span>├── test3.txt</span></span>
<span class="line"><span>├── .test4.txt</span></span>
<span class="line"><span>└── test.txt</span></span>
<span class="line"><span></span></span>
<span class="line"><span>2 directories, 7 files</span></span></code></pre></div><h3 id="示例-1" tabindex="-1">示例-1 <a class="header-anchor" href="#示例-1" aria-label="Permalink to “示例-1”">​</a></h3><p>统计当前目录的文件（不包括隐藏文件）。 运行以下命令以确定当前目录中有多少个文件，并且不计算点文件（LCTT 译注：点文件即以“.” 开头的文件，它们在 Linux 默认是隐藏的）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -l . | egrep -c &#39;^-&#39;</span></span>
<span class="line"><span>4</span></span></code></pre></div><p><strong>细节：</strong></p><ul><li><code>ls</code> ： 列出目录内容</li><li><code>-l</code> ： 使用长列表格式</li><li><code>.</code> ： 列出有关文件的信息（默认为当前目录）</li><li><code>|</code> ： 将一个程序的输出发送到另一个程序进行进一步处理的控制操作符</li><li><code>egrep</code> ： 打印符合模式的行</li><li><code>-c</code> ： 通用输出控制</li><li><code>&#39;^-&#39;</code> ： 以“-”开头的行（<code>ls -l</code> 列出长列表时，行首的 “-” 代表普通文件）</li></ul><h3 id="示例-2" tabindex="-1">示例-2 <a class="header-anchor" href="#示例-2" aria-label="Permalink to “示例-2”">​</a></h3><p>统计当前目录包含隐藏文件在内的文件。 包括当前目录中的点文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -la . | egrep -c &#39;^-&#39;</span></span>
<span class="line"><span>5</span></span></code></pre></div><h3 id="示例-3" tabindex="-1">示例-3 <a class="header-anchor" href="#示例-3" aria-label="Permalink to “示例-3”">​</a></h3><p>运行以下命令来计数当前目录的文件和文件夹。 它会计算所有的文件和目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -l | wc -l</span></span>
<span class="line"><span>5</span></span></code></pre></div><p><strong>细节：</strong></p><ul><li><code>ls</code> ： 列出目录内容</li><li><code>-l</code> ： 使用长列表格式</li><li><code>|</code> ： 将一个程序的输出发送到另一个程序进行进一步处理的控制操作符</li><li><code>wc</code> ： 这是一个统计每个文件的换行符、单词和字节数的命令</li><li><code>-l</code> ： 输出换行符的数量</li></ul><h3 id="示例-4" tabindex="-1">示例-4 <a class="header-anchor" href="#示例-4" aria-label="Permalink to “示例-4”">​</a></h3><p>统计当前目录包含隐藏文件和目录在内的文件和文件夹。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># ls -la | wc -l</span></span>
<span class="line"><span>8</span></span></code></pre></div><h3 id="示例-5" tabindex="-1">示例-5 <a class="header-anchor" href="#示例-5" aria-label="Permalink to “示例-5”">​</a></h3><p>递归计算当前目录的文件，包括隐藏文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find . -type f | wc -l</span></span>
<span class="line"><span>7</span></span></code></pre></div><p><strong>细节 ：</strong></p><ul><li><code>find</code> ： 搜索目录结构中的文件</li><li><code>-type</code> ： 文件类型</li><li><code>f</code> ： 常规文件</li><li><code>wc</code> ： 这是一个统计每个文件的换行符、单词和字节数的命令</li><li><code>-l</code> ： 输出换行符的数量</li></ul><h3 id="示例-6" tabindex="-1">示例-6 <a class="header-anchor" href="#示例-6" aria-label="Permalink to “示例-6”">​</a></h3><p>使用 <code>tree</code> 命令输出目录和文件数（不包括隐藏文件）。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tree | tail -1</span></span>
<span class="line"><span>2 directories, 5 files</span></span></code></pre></div><h3 id="示例-7" tabindex="-1">示例-7 <a class="header-anchor" href="#示例-7" aria-label="Permalink to “示例-7”">​</a></h3><p>使用包含隐藏文件的 <code>tree</code> 命令输出目录和文件计数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># tree -a | tail -1</span></span>
<span class="line"><span>2 directories, 7 files</span></span></code></pre></div><h3 id="示例-8" tabindex="-1">示例-8 <a class="header-anchor" href="#示例-8" aria-label="Permalink to “示例-8”">​</a></h3><p>运行下面的命令递归计算包含隐藏目录在内的目录数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find . -type d | wc -l</span></span>
<span class="line"><span>3</span></span></code></pre></div><h3 id="示例-9" tabindex="-1">示例-9 <a class="header-anchor" href="#示例-9" aria-label="Permalink to “示例-9”">​</a></h3><p>根据文件扩展名计数文件数量。 这里我们要计算 <code>.txt</code> 文件。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find . -name &quot;*.txt&quot; | wc -l</span></span>
<span class="line"><span>7</span></span></code></pre></div><h3 id="示例-10" tabindex="-1">示例-10 <a class="header-anchor" href="#示例-10" aria-label="Permalink to “示例-10”">​</a></h3><p>组合使用 <code>echo</code> 命令和 <code>wc</code> 命令统计当前目录中的所有文件。 <code>4</code> 表示当前目录中的文件数量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo *.* | wc</span></span>
<span class="line"><span>1       4      39</span></span></code></pre></div><h3 id="示例-11" tabindex="-1">示例-11 <a class="header-anchor" href="#示例-11" aria-label="Permalink to “示例-11”">​</a></h3><p>组合使用 <code>echo</code> 命令和 <code>wc</code> 命令来统计当前目录中的所有目录。 第二个 <code>1</code> 表示当前目录中的目录数量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo */ | wc</span></span>
<span class="line"><span>1       1       6</span></span></code></pre></div><h3 id="示例-12" tabindex="-1">示例-12 <a class="header-anchor" href="#示例-12" aria-label="Permalink to “示例-12”">​</a></h3><p>组合使用 <code>echo</code> 命令和 <code>wc</code> 命令来统计当前目录中的所有文件和目录。 <code>5</code> 表示当前目录中的目录和文件的数量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo * | wc</span></span>
<span class="line"><span>1 5 44</span></span></code></pre></div><h3 id="示例-13" tabindex="-1">示例-13 <a class="header-anchor" href="#示例-13" aria-label="Permalink to “示例-13”">​</a></h3><p>统计系统（整个系统）中的文件数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type f | wc -l</span></span>
<span class="line"><span>69769</span></span></code></pre></div><h3 id="示例-14" tabindex="-1">示例-14 <a class="header-anchor" href="#示例-14" aria-label="Permalink to “示例-14”">​</a></h3><p>统计系统（整个系统）中的文件夹数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type d | wc -l</span></span>
<span class="line"><span>8819</span></span></code></pre></div><h3 id="示例-15" tabindex="-1">示例-15 <a class="header-anchor" href="#示例-15" aria-label="Permalink to “示例-15”">​</a></h3><p>运行以下命令来计算系统（整个系统）中的文件、文件夹、硬链接和符号链接数。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># find / -type d -exec echo dirs \\; -o -type l -exec echo symlinks \\; -o -type f -links +1 -exec echo hardlinks \\; -o -type f -exec echo files \\; | sort | uniq -c</span></span>
<span class="line"><span>   8779 dirs</span></span>
<span class="line"><span>  69343 files</span></span>
<span class="line"><span>     20 hardlinks</span></span>
<span class="line"><span>  11646 symlinks</span></span></code></pre></div><hr>`,57)),l("p",null,[s[1]||(s[1]=a("via: ",-1)),i(e,{href:"https://www.2daygeek.com/how-to-count-the-number-of-files-and-folders-directories-in-linux/"},{default:n(()=>[...s[0]||(s[0]=[a("https://www.2daygeek.com/how-to-count-the-number-of-files-and-folders-directories-in-linux/",-1)])]),_:1})]),l("p",null,[s[5]||(s[5]=a("作者：",-1)),i(e,{href:"https://www.2daygeek.com/author/magesh/"},{default:n(()=>[...s[2]||(s[2]=[a("Magesh Maruthamuthu",-1)])]),_:1}),s[6]||(s[6]=a(" 译者：",-1)),i(e,{href:"https://github.com/Flowsnow"},{default:n(()=>[...s[3]||(s[3]=[a("Flowsnow",-1)])]),_:1}),s[7]||(s[7]=a(" 校对：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[4]||(s[4]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[8]||(s[8]=[a("LCTT",-1)])]),_:1}),s[11]||(s[11]=a(" 原创编译，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[9]||(s[9]=[a("Linux中国",-1)])]),_:1}),s[12]||(s[12]=a(" 荣誉推出",-1))])])}const C=t(c,[["render",r]]);export{y as __pageData,C as default};
